#pragma once

#include <string>
#include <vector>

namespace ncm::gearbox {

/// One manual configuration of one model: the TweakXL vehicle clone (`<base>_ncm_gbx_<spec>`, created by
/// r6/tweaks/ncm_gearbox/clones.yaml with `$base`) and the gearing core `machine.gearbox` computed for it.
/// Generated by tools/gen-gearbox-records.lua; never hand-edited.
struct CloneSpec {
    std::string record;          // the clone vehicle record
    std::string base;            // the model record it was cloned from
    std::string spec;            // spec id (m5, m6o...)
    std::vector<double> ratios;  // each forward gear's redline speed as a fraction of the reference top speed
    int shiftMs = 250;
    double topKph = 0.0;         // the reference: the catalogue's authored top speed (0 = none: the model's native top gear)
};

struct Specs {
    double gearHeadroom = 0.0;   // Carrier's stretch of an automatic's chain (parts.handling GEAR_HEADROOM); 0 = none
    bool reverseFirst = true;    // vanilla and the RB15 list reverse as gears[0]; S1 confirms or flips this
    std::vector<CloneSpec> clones;
};

/// Read `ncm_gearbox_specs.json` beside the DLL. Empty on any fault (logged).
Specs loadSpecs(const std::wstring& path);

/// Log the model's native engine data and gear chain (S1 evidence): every engine-data property with a flat, every
/// gear's band, torque multiplier and RPM range.
void dumpModel(const std::string& vehicleRecord);

/// Build the clone's own engine data and forward gears from the model's live values and point the clone at them.
/// Idempotent: a clone already pointing at its own engine data is left alone. Returns false (logged) on any refusal;
/// a refused clone keeps the model's engine data, i.e. drives exactly like the automatic.
bool buildClone(const CloneSpec& clone, bool reverseFirst, double gearHeadroom);

/// The number of native gears a manual clone carries (0.4.0).
constexpr int kSlices = 7;

/// 0.4.0, THE SLICES: repoint one native gear's band (min/max speed m/s, rpm window, torque multiplier) and re-read the
/// record, live. Never touches the live gearbox state (KB-330). True when the writes landed.
bool retuneSlice(uint64_t gearId, float minSpeedMps, float maxSpeedMps, float minRpm, float maxRpm, float torque);

}  // namespace ncm::gearbox
